/* Original, resolution-independent illustrations for the Buttercup kitchen. */
let illustrationId=0;
function softSvg(body,label,view='0 0 200 200',palette=['#fff6e2','#e2b57f']){const id='paint'+illustrationId++;return `<svg viewBox="${view}" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${id}" x1="0" y1="0" x2=".85" y2="1"><stop stop-color="${palette[0]}"/><stop offset="1" stop-color="${palette[1]}"/></linearGradient><radialGradient id="${id}glow" cx=".32" cy=".2" r=".9"><stop stop-color="#ffffff" stop-opacity=".65"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs><g stroke-linecap="round" stroke-linejoin="round">${body.replaceAll('PAINT',id)}</g></svg>`}
ingredientArt=function(name){if(name==='Honey')return softSvg(`<ellipse cx="100" cy="182" rx="55" ry="8" fill="#9d74531a"/><rect x="53" y="58" width="94" height="116" rx="26" fill="url(#PAINT)" stroke="#be9b61" stroke-width="2"/><rect x="57" y="42" width="86" height="24" rx="7" fill="#c7a8b6"/><path d="M65 50h70" stroke="#ead4dd" stroke-width="3"/><rect x="62" y="98" width="76" height="56" rx="17" fill="#fff5dc"/><text x="100" y="117" text-anchor="middle" font-family="Georgia" font-size="12" fill="#987545">Honey</text><circle cx="86" cy="134" r="3" fill="#775d52"/><circle cx="114" cy="134" r="3" fill="#775d52"/><path d="M95 143q5 5 10 0" stroke="#775d52" stroke-width="2" fill="none"/>`,name,'0 0 200 200',['#f8df99','#d6a151']);const palettes={Flour:['#fff2d7','#dcbf94'],Sugar:['#ffe7ed','#e6adc4'],'Baking soda':['#e2f2e8','#a8c8b0'],'Baking powder':['#eee7fb','#b7a7d2'],'Chocolate chips':['#e4c7af','#b48b70'],Cocoa:['#caa182','#98705c'],Salt:['#e5f2f8','#b3cbd6']};let body='';const face=`<g fill="#775d52"><ellipse cx="85" cy="133" rx="3" ry="4"/><ellipse cx="115" cy="133" rx="3" ry="4"/><path d="M95 143q5 5 10 0" stroke="#775d52" stroke-width="2.5" fill="none"/></g><ellipse cx="75" cy="143" rx="8" ry="4" fill="#e9adba" opacity=".6"/><ellipse cx="125" cy="143" rx="8" ry="4" fill="#e9adba" opacity=".6"/>`;let p=palettes[name]||['#fff6e2','#e2b57f'];
if(name==='Egg'){p=['#fff5df','#dfbd8c'];body=`<ellipse cx="100" cy="183" rx="48" ry="8" fill="#9d74531a"/><path d="M100 24C72 24 49 80 49 117c0 35 22 58 51 58s51-23 51-58c0-37-23-93-51-93Z" fill="url(#PAINT)" stroke="#c6a885" stroke-width="2"/><path d="M75 63q-15 27-13 47" stroke="#fff9ec" stroke-width="8" fill="none" opacity=".8"/>${face}`}
else if(name==='Butter'){p=['#fff4b8','#eccb70'];body=`<ellipse cx="100" cy="174" rx="77" ry="10" fill="#9d74531a"/><path d="M20 111l29-38 132 3 3 76-32 20-133-23Z" fill="#fff7e7" stroke="#d6c5aa" stroke-width="2"/><path d="M35 88Q35 77 48 77h111q12 0 12 12v49q0 13-14 13H48q-13 0-13-13Z" fill="url(#PAINT)" stroke="#d1b367" stroke-width="2"/><path d="M38 88h129M79 79v70M121 79v70" stroke="#fff7ce" stroke-width="3"/><path d="M27 148l25-5 26 26M170 138l13 14-31 20" fill="#f3dfb6" stroke="#d5c3a4" stroke-width="2"/>${face}`}
else if(['Milk','Vanilla','Lemon juice'].includes(name)){const milk=name==='Milk';p=milk?['#fffdf3','#d6e7e5']:name==='Vanilla'?['#bd9675','#7d5744']:['#fff2b9','#e5cb75'];body=`<ellipse cx="100" cy="183" rx="49" ry="8" fill="#9d74531a"/><path d="M78 32h44v25q0 8 11 19q14 12 14 27v61q0 12-14 12H67q-14 0-14-12v-61q0-15 14-27q11-11 11-19Z" fill="url(#PAINT)" stroke="${milk?'#adc5c6':'#aa8b65'}" stroke-width="2"/><rect class="bottle-cap" x="75" y="23" width="50" height="17" rx="6" fill="${milk?'#9ebed5':name==='Vanilla'?'#9fb58b':'#b8c68b'}"/><path d="M67 94v61" stroke="#fff" stroke-opacity=".45" stroke-width="7"/><rect x="62" y="101" width="76" height="55" rx="16" fill="#fff9eb"/><text x="100" y="118" font-size="${name==='Lemon juice'?9:11}" font-family="Georgia" text-anchor="middle" fill="#8d7763">${milk?'MILK':name==='Vanilla'?'Vanilla':'Lemon juice'}</text>${face}`}
else{body=`<ellipse cx="100" cy="183" rx="62" ry="8" fill="#9d74531a"/><path d="M56 32q44-7 88 0l-5 24q20 34 20 101q0 18-18 19H59q-18-1-18-19q0-67 20-101Z" fill="url(#PAINT)" stroke="#a99077" stroke-width="2"/><path d="M56 32q44 8 88 0M61 55q39 7 78 0" stroke="#fff6e6" stroke-width="4"/><path d="M54 85q-6 34-4 61" stroke="#fffaf0" stroke-opacity=".5" stroke-width="6"/><rect x="57" y="100" width="86" height="59" rx="19" fill="#fff9ef"/><text x="100" y="119" text-anchor="middle" fill="#8b725e" font-family="Georgia" font-size="${name.length>10?8.5:12}">${name}</text>${face}`}
return softSvg(body,name,'0 0 200 200',p)};
art=function(r,quality=1,frost=null){const bad=quality<.4,base=bad?'#b78260':'#e8bd82',cream=icingColor(frost||'Vanilla');let body='';if(r.id==='cookie'){body=[[-40,-20],[34,-25],[0,35]].map(([x,y],i)=>`<g transform="translate(${x} ${y}) rotate(${i*12-10})"><ellipse cy="6" rx="39" ry="34" fill="#b78b5d"/><ellipse rx="39" ry="34" fill="url(#PAINT)" stroke="#c89760" stroke-width="1.4"/><path d="M-24-16q18-15 39-4" stroke="#f9dba3" stroke-width="4" fill="none"/>${[[-18,-3],[4,-17],[21,3],[-4,14]].map(([a,b])=>`<path d="M${a-5} ${b-4}q5-5 11 0l1 6q-5 5-11 0Z" fill="#795244"/>`).join('')}${frost?`<path d="M-28-7q12-15 14 0t14 0t14 0t14 0" stroke="${cream}" stroke-width="4" fill="none"/>`:''}</g>`).join('')}
else if(r.id==='cupcake'){body=`<path d="M-47 4q47-13 94 0l-12 63q-35 13-70 0Z" fill="#dba2b8" stroke="#bf8fa5" stroke-width="1.5"/><path d="M-29 17l7 45M-10 20l2 46M10 20l-2 46M29 17l-7 45" stroke="#f5d5df" stroke-width="5"/><ellipse cy="4" rx="47" ry="18" fill="url(#PAINT)"/>${frost?`<path d="M-47-1C-63-19-33-29-27-29C-39-47-9-49-5-53C-9-64 4-74 10-78C6-59 43-53 31-34C59-23 61-5 47 2Q0 17-47-1Z" fill="${cream}" stroke="#b58a8c" stroke-opacity=".5" stroke-width="1.5"/><path d="M-30-21q28 12 61-3M-14-44q17 7 36 2" stroke="#fff" stroke-opacity=".4" stroke-width="5" fill="none"/>`:''}`}
else if(r.id==='brownie'){body=`<path d="M-64-22Q-69-28-60-31l80-21q7-2 13 3l38 31q5 4 3 11l-4 51q0 7-8 9l-80 21q-8 2-14-3l-30-25q-5-3-5-10Z" fill="#754c3e"/><path d="M-64-26l84-23 50 33-89 24Z" fill="url(#PAINT)"/><path d="M-55-21l20 4 13-12 20 6 19-14M-13-1l15-12 19 3 21-9" fill="none" stroke="#d8a07e" stroke-width="2.5"/>${frost?`<path d="M-45-18q22-15 18 0t22 0t22 0t22 0" fill="none" stroke="${cream}" stroke-width="5"/>`:''}`}
else if(r.id==='lemon'){body=`<path d="M-70-20q0-27 28-29l87 9q25 3 25 27l-7 57q-1 13-16 14l-95-9q-17-2-18-16Z" fill="url(#PAINT)" stroke="#c89f6c" stroke-width="1.5"/><path d="M-68-18q2-29 28-28l83 9q25 2 25 25l-6 4q-8 9-16-1q-9-10-15 6q-10 16-19-2q-8-11-18-1q-13 12-25-5q-8-10-20-1q-8 4-17-6Z" fill="${frost?cream:'#f4d999'}"/>${frost?'<ellipse cx="18" cy="-28" rx="17" ry="16" fill="#fff1ba" stroke="#ecd06f" stroke-width="4"/><path d="M18-40v24M6-28h24M9-37l18 18" stroke="#e9cf78" stroke-width="1.5"/>':''}`}
else{body=`<path d="M-64-20H64v70q-64 28-128 0Z" fill="url(#PAINT)" stroke="#cca480" stroke-width="1.5"/><path d="M-64 10q64 24 128 0v13q-64 25-128 0Z" fill="#f2c3cf"/><ellipse cy="-20" rx="64" ry="23" fill="${frost?cream:base}"/>${frost?`<path d="M-64-20v21q8 11 15-4v-9q9 17 18 3q10-12 16 3q9 18 18-2q8-15 16 0q8 12 17-2q10-12 17 2q11 12 11-11v-1" fill="${cream}"/><ellipse cx="-15" cy="-25" rx="31" ry="8" fill="#fff" opacity=".2"/>`:''}`}
const dense=quality<.8;return softSvg(`<ellipse cy="78" rx="87" ry="10" fill="#96724d18"/><g transform="${dense?'translate(0 20) scale(1 .7)':'translate(0 0)'}">${body}</g>`,r.name,'-105 -95 210 190',r.id==='brownie'?['#b07b60','#86553f']:['#f7d69b',base])};
const animalKinds=['squirrel','bunny','hamster','hedgehog','fox'];const animalNames=['Hazel the squirrel','Poppy the bunny','Mochi the hamster','Clover the hedgehog','Rosie the fox'];recipes.forEach((r,i)=>{r.customer=animalNames[i];r.animal=animalKinds[i]});
function animalArt(kind,stars=5){const bunny=kind==='bunny',fox=kind==='fox',ham=kind==='hamster',squirrel=kind==='squirrel',hedge=kind==='hedgehog';const fur=bunny?'#eedbc9':fox?'#dfa17c':ham?'#e5c19b':squirrel?'#c79b7a':'#c9ac92';let body='';if(squirrel)body+='<path d="M265 321C368 301 372 204 320 193C261 180 275 257 306 249C325 245 318 222 306 226" fill="#b88968" stroke="#a97b5e" stroke-width="3"/>';if(hedge)body+='<path d="M73 320Q34 271 73 211l-4-23 21 5 6-27 24 11 17-27 21 22 26-23 13 28 28-10 7 28 29-2-7 32q44 58 6 99Z" fill="#a28773"/>';body+=`<ellipse cx="180" cy="353" rx="112" ry="12" fill="#8c72551a"/><ellipse cx="180" cy="286" rx="90" ry="77" fill="${fur}"/><ellipse cx="180" cy="303" rx="59" ry="47" fill="#fff2dc"/><ellipse cx="129" cy="346" rx="34" ry="15" fill="${fur}"/><ellipse cx="231" cy="346" rx="34" ry="15" fill="${fur}"/>`;
if(bunny){body+=`<g class="animal-ears"><path d="M122 150C78 110 85 13 111 19C143 23 145 112 148 141" fill="${fur}" stroke="#cfb9a5" stroke-width="2"/><path d="M123 126C101 91 99 38 112 39C126 40 132 97 133 129" fill="#eabac3"/><path d="M211 143C210 107 213 16 241 19C270 24 257 116 237 151" fill="${fur}" stroke="#cfb9a5" stroke-width="2"/><path d="M225 129C222 94 227 39 239 40C251 42 241 101 233 131" fill="#eabac3"/></g>`}
else if(fox){body+=`<path d="M100 163L93 72Q91 55 106 65l64 71M204 137l60-72q15-14 13 8l-7 94" fill="${fur}" stroke="#c68c69" stroke-width="2"/><path d="M111 137l-4-53 41 56M223 141l41-56-6 56" fill="#edc1bd"/>`}
else{body+=`<circle cx="113" cy="126" r="34" fill="${fur}"/><circle cx="247" cy="126" r="34" fill="${fur}"/><circle cx="113" cy="126" r="21" fill="#e7b4b2"/><circle cx="247" cy="126" r="21" fill="#e7b4b2"/>`}
body+=`<path d="M180 114C124 108 78 143 79 197c0 53 40 79 101 79s101-26 101-79c1-54-45-89-101-83Z" fill="${fur}"/><ellipse cx="180" cy="218" rx="${ham?79:64}" ry="43" fill="#fff1de"/>${fox?'<path d="M90 183q36 4 69 44l-39 19q-34-15-30-63M270 183q-36 4-69 44l39 19q34-15 30-63" fill="#fff1de"/>':''}<g class="animal-eyes" fill="#69534a"><ellipse cx="139" cy="190" rx="7" ry="9"/><ellipse cx="221" cy="190" rx="7" ry="9"/><circle cx="141" cy="187" r="2.5" fill="#fff"/><circle cx="223" cy="187" r="2.5" fill="#fff"/></g><ellipse cx="115" cy="212" rx="17" ry="9" fill="#e9aeb7" opacity=".8"/><ellipse cx="245" cy="212" rx="17" ry="9" fill="#e9aeb7" opacity=".8"/><path d="M174 208q6-5 12 0q-1 8-6 8q-5 0-6-8" fill="#b48383"/><path d="M180 216v5m-11 1q11 ${stars>=3?12:5} 22 0" stroke="#97736a" stroke-width="2.5" fill="none"/>${squirrel?'<path d="M171 232h18v12h-18z" fill="#fff" rx="4"/>':''}<path d="M172 127q10-18 20-9q-5 2-7 9" fill="${fur}"/><path d="M145 266q34 16 70 0l7 65h-85Z" fill="${bunny?'#d5a8bb':fox?'#a8bc9a':ham?'#bec6db':'#c6cda5'}"/><path d="M154 269l-8-22M205 269l8-22" stroke="#f9f0db" stroke-width="5"/>`;
return softSvg(body.replaceAll('fill="'+fur+'"','fill="url(#PAINT)"'),`Cute ${kind} customer`,'0 0 360 370',[fur,'#c39e7f'])}
function pawsArt(){return '<svg class="holding-paws" viewBox="0 0 360 370" aria-hidden="true"><ellipse cx="105" cy="304" rx="24" ry="16" fill="#eed7bd" stroke="#c7a78d" stroke-width="1.5" transform="rotate(15 105 304)"/><ellipse cx="255" cy="304" rx="24" ry="16" fill="#eed7bd" stroke="#c7a78d" stroke-width="1.5" transform="rotate(-15 255 304)"/></svg>'}

// Containers have different silhouettes and true relative sizes on a common shelf baseline.
const originalIngredientArt=ingredientArt;
ingredientArt=function(name){
if(name==='Egg')return originalIngredientArt(name).replace('<g stroke-linecap="round"','<g transform="translate(40 70) scale(.6)" stroke-linecap="round"');
if(name==='Butter')return originalIngredientArt(name).replace('<g stroke-linecap="round"','<g transform="translate(15 27) scale(.85)" stroke-linecap="round"');
const face=(x,y,scale=1)=>`<g transform="translate(${x} ${y}) scale(${scale})"><circle cx="-12" cy="0" r="2.6" fill="#765d4f"/><circle cx="12" cy="0" r="2.6" fill="#765d4f"/><path d="M-4 8q4 4 8 0" fill="none" stroke="#765d4f" stroke-width="2"/><ellipse cx="-21" cy="8" rx="6" ry="3" fill="#e6a5b0" opacity=".6"/><ellipse cx="21" cy="8" rx="6" ry="3" fill="#e6a5b0" opacity=".6"/></g>`;
const label=(x,y,w,h,text,size=11)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${Math.min(13,h/3)}" fill="#fff7e8"/><text x="${x+w/2}" y="${y+17}" font-size="${size}" text-anchor="middle" font-family="Georgia" fill="#8c7159">${text}</text>`;
let body='',palette=['#fff2d7','#d9bc95'];
if(name==='Flour'){body=`<path d="M45 30q55-9 110 0l-9 24q24 43 28 107q1 17-19 18H45q-20-1-19-18q4-64 29-107Z" fill="url(#PAINT)" stroke="#b89b77" stroke-width="2"/><path d="M45 30q55 11 110 0M55 54q45 9 90 0" stroke="#fdf3db" stroke-width="5"/><path d="M41 81q-8 32-7 65" fill="none" stroke="#fff8e6" stroke-width="7" opacity=".55"/>${label(54,90,92,66,'FLOUR',15)}<path d="M100 70v14m-2-8l-6-5m10 5l6-5" stroke="#b69a63" stroke-width="2"/>${face(100,131)}`}
else if(name==='Sugar'){palette=['#fffcf1','#e8e5d8'];body=`<path d="M53 79q-7 10-7 25v57q0 19 20 19h68q20 0 20-19v-57q0-15-7-25Z" fill="url(#PAINT)" stroke="#b0bdb8" stroke-width="2"/><path d="M50 116q50-13 100 0v45q0 15-18 15H68q-18 0-18-15Z" fill="#f9e8e7"/><rect x="47" y="58" width="106" height="23" rx="9" fill="#e2b2c3" stroke="#c995aa" stroke-width="2"/><path d="M58 66h84" stroke="#f4d5e1" stroke-width="4"/><path d="M57 93v64" stroke="#fff" stroke-width="6" opacity=".65"/>${label(64,113,72,47,'Sugar',12)}${face(100,142,.7)}`}
else if(name==='Chocolate chips'){palette=['#cfac90','#ab8268'];body=`<path d="M39 57l12-5 12 4 12-5 12 4 13-4 13 4 12-4 13 4 14-4 11 7-8 31 9 78-13 12H49l-14-12 11-78Z" fill="url(#PAINT)" stroke="#96715b" stroke-width="2"/><path d="M48 67h105M46 159l10 11h88l10-11" stroke="#e2c5ac" stroke-width="3"/><path d="M47 87l-4 76M153 87l4 76" stroke="#94715e" stroke-width="2"/>${label(52,82,96,57,'Choc chips',12)}<g fill="#795449"><path d="M70 153q9-17 12-17q11 15 6 20q-13 6-18-3"/><path d="M111 153q9-17 12-17q11 15 6 20q-13 6-18-3"/></g>${face(100,119,.7)}`}
else if(name==='Baking powder'){palette=['#eee7fa','#c9bbdc'];body=`<path d="M62 88v82q0 12 38 12t38-12V88" fill="url(#PAINT)" stroke="#a898bf" stroke-width="2"/><ellipse cx="100" cy="88" rx="38" ry="9" fill="#e5d9ef"/><rect x="59" y="75" width="82" height="15" rx="6" fill="#b5a1ca"/><path d="M66 80h68" stroke="#d7cbe5" stroke-width="3"/>${label(68,107,64,52,'Baking',10)}<text x="100" y="133" font-size="9" text-anchor="middle" font-family="Georgia" fill="#8c7159">powder</text>${face(100,147,.55)}`}
else if(name==='Baking soda'){palette=['#d9e9d7','#a8c4ab'];body=`<path d="M60 83l14-9h63v99l-14 8H60Z" fill="url(#PAINT)" stroke="#8da68d" stroke-width="2"/><path d="M60 83h64l13-9M124 83v98" fill="none" stroke="#e9f3e3" stroke-width="3"/>${label(67,103,50,58,'Baking',9)}<text x="92" y="130" font-family="Georgia" text-anchor="middle" font-size="9" fill="#8c7159">soda</text>${face(92,146,.5)}`}
else if(name==='Salt'){palette=['#ecf2ee','#cbd9d6'];body=`<path d="M76 125q-8 6-8 18v24q0 14 32 14t32-14v-24q0-12-8-18Z" fill="url(#PAINT)" stroke="#a1b4b2" stroke-width="2"/><path d="M75 125v-11q25-15 50 0v11Z" fill="#b7c4ca" stroke="#93a4aa" stroke-width="2"/><g fill="#8e9fa4"><circle cx="89" cy="113" r="1.8"/><circle cx="100" cy="109" r="1.8"/><circle cx="111" cy="113" r="1.8"/></g>${label(75,135,50,33,'Salt',10)}${face(100,160,.48)}`}
else if(name==='Cocoa'){palette=['#bb8c6b','#94694f'];body=`<path d="M50 114v51q0 16 50 16t50-16v-51" fill="url(#PAINT)" stroke="#8f684f" stroke-width="2"/><ellipse cx="100" cy="114" rx="50" ry="10" fill="#c9a583"/><rect x="47" y="101" width="106" height="16" rx="7" fill="#997760"/>${label(61,125,78,41,'Cocoa',12)}${face(100,151,.6)}`}
else if(name==='Cinnamon'){palette=['#d1aa7e','#b28b64'];body=`<rect x="73" y="123" width="54" height="58" rx="11" fill="url(#PAINT)" stroke="#a78963" stroke-width="2"/><rect x="70" y="111" width="60" height="16" rx="5" fill="#be9299"/>${label(77,134,46,32,'Cinnamon',7)}${face(100,162,.4)}`}
else if(name==='Milk'){palette=['#fffdf4','#d7e7e5'];body=`<path d="M72 28h56v25q0 10 14 21q18 14 18 36v52q0 18-20 18H60q-20 0-20-18v-52q0-22 18-36q14-11 14-21Z" fill="url(#PAINT)" stroke="#adc1bf" stroke-width="2"/><rect class="bottle-cap" x="68" y="17" width="64" height="20" rx="7" fill="#a5c4d7"/><path d="M54 95v59" stroke="#fff" stroke-width="8" opacity=".75"/>${label(57,105,86,56,'MILK',15)}${face(100,141,.9)}`}
else if(name==='Vanilla'){palette=['#b18c68','#79543d'];body=`<path d="M88 111h24v10l10 12v37q0 11-11 11H89q-11 0-11-11v-37l10-12Z" fill="url(#PAINT)" stroke="#87694f" stroke-width="2"/><rect class="bottle-cap" x="84" y="99" width="32" height="15" rx="4" fill="#91a485"/>${label(82,138,36,31,'Vanilla',7)}${face(100,162,.37)}`}
else if(name==='Lemon juice'){palette=['#fff0ae','#d8c16e'];body=`<path d="M84 92h32v15q18 10 18 28v34q0 12-14 12H80q-14 0-14-12v-34q0-18 18-28Z" fill="url(#PAINT)" stroke="#c0ad66" stroke-width="2"/><rect class="bottle-cap" x="80" y="80" width="40" height="15" rx="4" fill="#b0bd87"/>${label(72,130,56,37,'Lemon',9)}${face(100,158,.5)}`}
else if(name==='Honey'){palette=['#f4d98e','#d1a050'];body=`<rect x="52" y="99" width="96" height="82" rx="25" fill="url(#PAINT)" stroke="#b79454" stroke-width="2"/><rect class="bottle-cap" x="54" y="84" width="92" height="20" rx="7" fill="#c7a9b8"/><path d="M63 91h74" stroke="#e6ced9" stroke-width="3"/><path d="M62 114v36" stroke="#fff" stroke-width="6" opacity=".4"/>${label(65,124,70,43,'Honey',12)}${face(100,153,.65)}<path d="M139 79l16-25" stroke="#b28c5b" stroke-width="6"/><ellipse cx="157" cy="49" rx="12" ry="18" fill="#e5c18a" transform="rotate(30 157 49)"/><path d="M149 43l16 9M146 49l16 9" stroke="#bd965e" stroke-width="2"/>`}
else return originalIngredientArt(name);
return softSvg(`<ellipse cx="100" cy="185" rx="${name==='Flour'?75:name==='Vanilla'?28:50}" ry="5" fill="#9d745313"/>${body}`,name,'0 0 200 200',palette)
};
